#!/usr/bin/env python3
"""Standalone exact verifier for the threshold refutation and two cover families.

Standard library only. No optimization package or repository module is imported.
Finite certificates are embedded at the end. Every verdict uses Fraction or integer
polynomial arithmetic. Incidences are independently recomputed by position DP.
"""
import sys
sys.dont_write_bytecode = True
import argparse
from collections import defaultdict
from fractions import Fraction as F
from functools import lru_cache
from itertools import product
import json


def require(condition, message):
    if not condition:
        raise AssertionError(message)


@lru_cache(None)
def prefix_hist(fixed, counted):
    h = {0: 1}
    for a, b in zip(fixed, counted):
        nxt = defaultdict(int)
        for d, count in h.items():
            for letter in ((2, 3) if b == 2 else (b,)):
                nxt[d + (a != letter)] += count
        h = nxt
    return tuple(sorted(h.items()))


@lru_cache(None)
def tail_hist(C, fixed_weight, counted_weight):
    """Enumerate distance and counted weight one position at a time, exactly."""
    h = {(0, 0): 1}
    for i in range(C):
        fixed = 1 if i < fixed_weight else 0
        nxt = defaultdict(int)
        for (w, d), count in h.items():
            for letter in range(4):
                ww = w + (letter != 0)
                if ww <= counted_weight:
                    nxt[(ww, d + (letter != fixed))] += count
        h = nxt
    return tuple((d, count) for (w, d), count in sorted(h.items())
                 if w == counted_weight)


@lru_cache(None)
def ball_share(N, radius, fixed, counted):
    prefix, fixed_weight = fixed
    orbit_prefix, counted_weight = counted
    C = N - len(prefix)
    ph = prefix_hist(prefix, orbit_prefix)
    th = tail_hist(C, fixed_weight, counted_weight)
    total = sum(x for _, x in ph) * sum(x for _, x in th)
    inside = sum(x*y for d, x in ph for e, y in th if d+e <= radius)
    return F(inside, total)


@lru_cache(None)
def min_distance(prefix):
    L = len(prefix)
    return min(sum(x != y for x, y in zip(prefix, (0,)*j+(1,)*(L-j)))
               for j in range(L+1))


def labels(N, r, radius=None):
    C = N-r+1
    require(C >= 0, 'invalid library size')
    for prefix in product(range(3), repeat=r-1):
        hi = C if radius is None else min(C, radius-min_distance(prefix))
        for weight in range(hi+1):
            yield prefix, weight


def support_from_data(data):
    return [((tuple(map(int, t)), w), F(v)) for t, w, v in data]


def packing_check(N, r, radius, support):
    require(all(v >= 0 for _, v in support), 'negative packing coefficient')
    require(all(min_distance(t)+w <= radius for (t, w), _ in support),
            'packing support outside U')
    worst, witness, checked = F(0), None, 0
    for centre in labels(N, r):
        load = sum((v*ball_share(N, radius, centre, q) for q, v in support), F(0))
        checked += 1
        if load > worst:
            worst, witness = load, centre
    require(worst <= 1, 'packing FAILED: max load %s at %s' % (worst, witness))
    return sum((v for _, v in support), F(0)), worst, checked


def cover_check(N, r, radius, support):
    require(all(v >= 0 for _, v in support), 'negative cover coefficient')
    least, witness, checked = None, None, 0
    for point in labels(N, r, radius):
        covered = sum((v*ball_share(N, radius, point, c) for c, v in support), F(0))
        checked += 1
        if least is None or covered < least:
            least, witness = covered, point
    require(least >= 1, 'cover FAILED: min coverage %s at %s' % (least, witness))
    return sum((v for _, v in support), F(0)), least, checked


R5_GROUPS = [ [('0000',0),('1111',0)], [('0001',1),('0111',1)],
              [('0011',0)], [('0011',1)], [('0012',0),('2011',0)],
              [('0100',0),('1010',0),('1101',0)], [('0112',0),('2001',0)] ]


def r5_family(N, radius):
    C, m = N-4, radius
    den = 6*m*(3*m-5)
    numerators = [12*m*m-15*m-6, 18*C*(m-2), 6*m*m-21*m-6,
                  18*C, 20, 3*(m-2), 18*m-40]
    return [((tuple(map(int,t)),p), F(v,den))
            for group,v in zip(R5_GROUPS,numerators) for t,p in group]


# Polynomials are coefficient lists in increasing degree in z.
R6_GROUPS = [ [('00000',0),('11111',0)], [('00000',1),('11111',1)],
              [('00001',0),('01111',0)], [('00001',1),('01111',1)],
              [('00011',1),('00111',1)], [('00012',0),('20111',0)],
              [('00100',0),('11011',0)], [('00110',1),('10011',1)],
              [('00112',0),('20011',0)], [('01001',0),('01101',0)],
              [('01112',0),('20001',0)], [('01121',0),('02001',0)],
              [('10000',0),('11110',0)], [('10012',0),('20110',0)] ]


def p_add(a,b):
    ans=[F(0)]*max(len(a),len(b))
    for i,v in enumerate(a):ans[i]+=v
    for i,v in enumerate(b):ans[i]+=v
    return ans


def p_scale(a,x):return [v*x for v in a]


def p_mul(a,b):
    ans=[F(0)]*(len(a)+len(b)-1)
    for i,v in enumerate(a):
        for j,w in enumerate(b):ans[i+j]+=v*w
    return ans


R6_NUMERATORS = [ [69500,76599,26442,2808],
 p_scale(p_mul([11,5],[161,66]),3), [46411,49671,16524,1674],
 p_scale(p_mul([11,5],[524,441,72]),3),
 p_scale(p_mul([11,5],[2267,1626,234]),3), [4876,3498,432],
 [274,255,36], p_scale(p_mul([29,4],[11,5]),9), [5712,4236,684],
 [1007,639,72], [622,564,72], [2014,1278,144], [572,318,36], [422,102] ]
R6_DEN = [77345,84681,28935,3024]
R6_OVER_C = {1:[483,198],3:[1572,1323,216],4:[6801,4878,702],7:[261,36]}


def p_eval(poly,x):
    ans=F(0)
    for v in reversed(poly):ans=ans*x+v
    return ans


def r6_family(z, repaired=True):
    den = p_eval(R6_DEN,z) + (0 if repaired else 12*z+87)
    return [((tuple(map(int,t)),p),p_eval(num,z)/den)
            for group,num in zip(R6_GROUPS,R6_NUMERATORS) for t,p in group]


def cum(prefix, counted, k):
    h=prefix_hist(prefix,tuple(map(int,counted)))
    return F(sum(n for d,n in h if d<=k),sum(n for _,n in h))


def finite_row_count(L):
    return sum(L-min_distance(t)+1 for t in product(range(3),repeat=L))+1


def r6_symbolic_proof():
    """Check coefficient positivity after z=u+3, for every orbit and radial case."""
    from math import comb
    def shift(poly):
        ans=[F(0)]*len(poly)
        for j,v in enumerate(poly):
            for i in range(j+1):ans[i]+=v*comb(j,i)*3**(j-i)
        return ans
    require(all(v>=0 for num in R6_NUMERATORS for v in shift(num)),
            'r6 numerator coefficient failure')
    require(all(v>=0 for v in shift(R6_DEN)) and p_eval(R6_DEN,3)>0,
            'r6 denominator positivity failure')
    mass_num=[F(0)]
    for group,num in zip(R6_GROUPS,R6_NUMERATORS):
        mass_num=p_add(mass_num,p_scale(num,len(group)))
    gap=p_add(p_scale(R6_DEN,6),p_scale(mass_num,-1))
    require(gap==[676,1026,180,0], 'r6 gap identity failed')
    unique=set(); proof_rows=[]
    for prefix in product(range(3),repeat=5):
        for k in range(min_distance(prefix),6):
            slack=p_scale(R6_DEN,-1)
            for j,(group,num) in enumerate(zip(R6_GROUPS,R6_NUMERATORS)):
                for t,p in group:
                    if p==0:
                        term=p_scale(num,cum(prefix,t,k))
                    else:
                        lo,mid,hi=(cum(prefix,t,k+d) for d in (-1,0,1))
                        term=p_add(p_scale(num,lo),p_scale(
                            p_mul(R6_OVER_C[j],[8-k,3]),-lo+F(2,3)*mid+F(1,3)*hi))
                    slack=p_add(slack,term)
            shifted=shift(slack)
            require(all(v>=0 for v in shifted),
                    'r6 polynomial FAILED at %s k=%s: %s' % (prefix,k,shifted))
            unique.add(tuple(slack))
            proof_rows.append((''.join(map(str,prefix)),k,shifted))
    total_slack=p_add(mass_num,p_scale(R6_DEN,-1))
    require(all(v>=0 for v in shift(total_slack)), 'r6 interior case failed')
    unique.add(tuple(total_slack))
    proof_rows.append(('ALL',6,shift(total_slack)))
    print('PROVED r6 family: %d radial inequalities; %d distinct polynomial vectors; z>=3'
          % (finite_row_count(5),len(unique)))
    return proof_rows


# Bivariate polynomials in a=m-6 and b=C-m, represented as exact coefficient maps.
def b_const(x):return {(0,0):F(x)}


def b_add(a,b):
    ans=dict(a)
    for k,v in b.items():ans[k]=ans.get(k,F(0))+v
    return {k:v for k,v in ans.items() if v}


def b_scale(a,x):return {k:v*x for k,v in a.items() if v*x}


def b_mul(a,b):
    ans={}
    for (i,j),v in a.items():
        for (k,l),w in b.items():
            key=(i+k,j+l);ans[key]=ans.get(key,F(0))+v*w
    return {k:v for k,v in ans.items() if v}


def r5_symbolic_proof():
    m={(1,0):F(1),(0,0):F(6)}
    C={(1,0):F(1),(0,1):F(1),(0,0):F(6)}
    mm=b_mul(m,m);m2=b_add(m,b_const(-2))
    den=b_add(b_scale(mm,18),b_scale(m,-30))
    nums=[b_add(b_add(b_scale(mm,12),b_scale(m,-15)),b_const(-6)),
          b_scale(b_mul(C,m2),18),
          b_add(b_add(b_scale(mm,6),b_scale(m,-21)),b_const(-6)),
          b_scale(C,18),b_const(20),b_scale(m2,3),b_add(b_scale(m,18),b_const(-40))]
    overC={1:b_scale(m2,18),3:b_const(18)}
    require(all(v>=0 for num in nums for v in num.values()),'r5 weight positivity')
    require(all(v>=0 for v in den.values()) and den.get((0,0),0)>0,'r5 denominator positivity')
    mass={}
    for group,num in zip(R5_GROUPS,nums):mass=b_add(mass,b_scale(num,len(group)))
    unique=set(); proof_rows=[]
    for prefix in product(range(3),repeat=4):
        for k in range(min_distance(prefix),5):
            slack=b_scale(den,-1)
            for j,(group,num) in enumerate(zip(R5_GROUPS,nums)):
                for t,p in group:
                    if p==0:
                        term=b_scale(num,cum(prefix,t,k))
                    else:
                        lo,mid,hi=(cum(prefix,t,k+d) for d in (-1,0,1))
                        term=b_add(b_scale(num,lo),b_scale(
                            b_mul(overC[j],b_add(m,b_const(-k))),-lo+F(2,3)*mid+F(1,3)*hi))
                    slack=b_add(slack,term)
            require(all(v>=0 for v in slack.values()),
                    'r5 polynomial FAILED at %s k=%s: %s' % (prefix,k,slack))
            unique.add(tuple(sorted(slack.items())))
            proof_rows.append((''.join(map(str,prefix)),k,slack))
    total_slack=b_add(mass,b_scale(den,-1))
    require(all(v>=0 for v in total_slack.values()), 'r5 interior case failed')
    unique.add(tuple(sorted(total_slack.items())))
    proof_rows.append(('ALL',5,total_slack))
    print('PROVED r5 family: %d radial inequalities; %d distinct polynomial vectors; C>=m>=6'
          % (finite_row_count(4),len(unique)))
    return proof_rows


def small_cube_check():
    N,r=4,3
    def words(label):
        t,w=label;C=N-len(t)
        for pre in product(*[((2,3) if x==2 else (x,)) for x in t]):
            for tail in product(range(4),repeat=C):
                if sum(x!=0 for x in tail)==w:yield pre+tail
    orbit_words={q:list(words(q)) for q in labels(N,r)}
    checked=0
    for fixed in labels(N,r):
        t,p=fixed;c=t+(1,)*p+(0,)*(N-len(t)-p)
        for q,ws in orbit_words.items():
            ds=[sum(a!=b for a,b in zip(c,x)) for x in ws]
            for radius in range(N+1):
                direct=F(sum(d<=radius for d in ds),len(ws))
                require(direct==ball_share(N,radius,fixed,q),'small-cube incidence mismatch')
                checked+=1
    print('VERIFIED-COMPUTATIONALLY direct four-letter enumeration: %d incidences' % checked)


def finite_certificates():
    for rec in CERTIFICATES:
        N,r,m=rec['N'],rec['r'],rec['m']
        pm=None
        if 'packing' in rec:
            pm,_,_=packing_check(N,r,m,support_from_data(rec['packing']))
        if 'cover' in rec:
            cm,_,_=cover_check(N,r,m,support_from_data(rec['cover']))
            require(cm<r,'stored cover is not strictly short')
            if rec.get('matching'):
                require(pm==cm,'primal/dual mismatch')
        else:
            require(pm==r,'stored full-mass packing has wrong mass')
    print('VERIFIED-COMPUTATIONALLY %d embedded certificates, including all n=10..22 r=5 boundaries'
          % len(CERTIFICATES))


def find_certificate(N,r,m):
    return next(x for x in CERTIFICATES if (x['N'],x['r'],x['m'])==(N,r,m))


def controls(name):
    rec=find_certificate(16,6,8)
    if name=='underweight-cover':
        sup=[(q,v*F(999,1000))for q,v in support_from_data(rec['cover'])]
        cover_check(16,6,8,sup)
    elif name=='overweight-packing':
        sup=[(q,v*F(1001,1000))for q,v in support_from_data(rec['packing'])]
        packing_check(16,6,8,sup)
    elif name=='r5-outside-domain':cover_check(9,5,4,r5_family(9,4))
    elif name=='r6-outside-domain':cover_check(26,6,14,r6_family(2))
    elif name=='unrepaired-r6':cover_check(31,6,17,r6_family(3,repaired=False))
    else:raise ValueError(name)
    raise RuntimeError('CONTROL ERROR: deliberately invalid certificate was accepted')


def extension_check(N,s,r,base_mass):
    require(s<=r<=N+1,'invalid extension range')
    for j in range(s):
        original=(0,)*j+(1,)*(s-1-j)+(0,)*(N-s+1)
        image=tuple(1-x if s-1<=i<=r-2 else x for i,x in enumerate(original))
        target=(0,)*j+(1,)*(r-1-j)+(0,)*(N-r+1)
        require(image==target,'sublibrary isometry identity failed')
    require(base_mass+r-s<r,'extension mass inequality failed')


def family_list_checks(ns,rs,zs):
    for n in ns:
        N=n-1;m=(3*n-11)//5+1
        require(n>=10,'r5 upper theorem is stated for n>=10')
        support=(support_from_data(find_certificate(N,5,m)['cover'])
                 if N in (9,10) else r5_family(N,m))
        mass,least,checked=cover_check(N,5,m,support)
        require(mass<5,'r5 family is not short')
        for r in rs:
            if 5<=r<=N+1:
                extension_check(N,5,r,mass)
        print('VERIFIED-COMPUTATIONALLY r5 family n=%d m=%d mass=%s minimum=%s classes=%d'
              % (n,m,mass,least,checked))
    for z in zs:
        require(z>=3,'analytic r6 family requires z>=3')
        N,m=16+5*z,8+3*z
        mass,least,checked=cover_check(N,6,m,r6_family(z))
        require(mass==6-F(2*(90*z*z+513*z+338),p_eval(R6_DEN,z)), 'r6 mass formula mismatch')
        require(mass<6,'r6 family is not short')
        for r in rs:
            if 6<=r<=N+1:extension_check(N,6,r,mass)
        print('VERIFIED-COMPUTATIONALLY r6 refutation N=%d m=%d mass=%s minimum=%s classes=%d'
              % (N,m,mass,least,checked))
    print('PROVED extension reduction used for requested r=%s; additional library balls have weight 1' % rs)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--n',nargs='+',type=int,default=list(range(10,23))+[27,32,52,102])
    parser.add_argument('--r',nargs='+',type=int,default=[5,6,7,17])
    parser.add_argument('--z',nargs='+',type=int,default=[3,4,10,20])
    parser.add_argument('--control',choices=['underweight-cover','overweight-packing',
        'r5-outside-domain','r6-outside-domain','unrepaired-r6'])
    parser.add_argument('--algebra-only',action='store_true')
    args=parser.parse_args()
    if args.control:controls(args.control);return
    r5_symbolic_proof();r6_symbolic_proof()
    if args.algebra_only:return
    small_cube_check();finite_certificates();family_list_checks(args.n,args.r,args.z)
    print('PASS: every exact certificate and every symbolic identity accepted')


